//----------------------------------------------------------------------------//
// Formats

// Enumerator values are the matching VkFormat values, as stored in the file
enum class Format : uint32_t
{
    Undefined     = 0,
    R8_UNORM      = 9,
    R8_UINT       = 13,
    RG8_UNORM     = 16,
    RG8_UINT      = 20,
    RGBA8_UNORM   = 37,
    RGBA8_UINT    = 41,
    R32_UINT      = 98,
    R32_SFLOAT    = 100,
    RG32_UINT     = 101,
    RG32_SFLOAT   = 103,
    RGBA32_UINT   = 107,
    RGBA32_SFLOAT = 109,
    R64_UINT      = 110,
    R64_SFLOAT    = 112,
    RG64_UINT     = 113,
    RG64_SFLOAT   = 115,
    RGBA64_UINT   = 119,
    RGBA64_SFLOAT = 121
};

enum class ComponentType { Invalid, UNorm, UInt, SFloat };

struct FormatInfo
{
    uint32_t      channels;        // 1, 2 or 4; 0 if the format is unsupported
    uint32_t      bytesPerChannel; // 1, 4 or 8
    ComponentType type;
    uint32_t texelSize() const {return channels*bytesPerChannel;}
    bool valid() const {return channels != 0;}
};

FormatInfo formatInfo(Format format);

// Bytes per texel, 0 for unsupported formats
uint32_t texelSize(Format format);

//----------------------------------------------------------------------------//
// Supercompression (lossless, applied to each mip level independently).
// Enumerator values are the scheme ids stored in the file

enum class Supercompression : uint32_t { None = 0, Zstd = 2 };

//----------------------------------------------------------------------------//
// Texture

struct Texture
{
    Format   format     = Format::Undefined;
    uint32_t dimensions = 2; // 1, 2 or 3
    uint32_t width      = 0;
    uint32_t height     = 1; // Ignored (treated as 1) for 1D textures
    uint32_t depth      = 1; // Ignored (treated as 1) for 1D and 2D textures
    uint32_t layers     = 0; // 0 = not an array texture, N >= 1 = N layers
    uint32_t faces      = 1; // 1, or 6 for a cube map (2D, square)

    // levels[0] is the base (largest) mip level. See TEXEL DATA LAYOUT above
    std::vector<std::vector<uint8_t>> levels;

    // Key/value metadata as text. On write, "KTXwriter" is added if absent.
    // Useful keys: "KTXorientation" (see ROW ORDER above). Custom keys are
    // allowed; `ktx validate` merely warns about them
    std::map<std::string, std::string> metadata;

    uint32_t levelWidth(uint32_t level) const;
    uint32_t levelHeight(uint32_t level) const;
    uint32_t levelDepth(uint32_t level) const;
    // Expected byte size of one mip level (all layers and faces); 0 if the
    // format is unsupported or the size does not fit in 64 bits
    uint64_t levelSize(uint32_t level) const;
};

// The kinds of texture vir has, for decodeKtx2
enum class Kind { Texture2D, Texture3D, CubeMap };

// Maximum number of mip levels for a texture of the given base size
uint32_t maxLevelCount(uint32_t width, uint32_t height=1, uint32_t depth=1);

// Single-level textures. The base level is copied from 'data' (levelSize(0)
// bytes) or zero-filled if data == nullptr
Texture make1D(Format format, uint32_t width, const void* data=nullptr);
Texture make2D
(
    Format format, uint32_t width, uint32_t height, const void* data=nullptr
);
Texture make3D
(
    Format format, uint32_t width, uint32_t height, uint32_t depth,
    const void* data=nullptr
);

// True if the first row of each image is the top one ("KTXorientation" says
// 'd', or is absent, which KTX defines as "rd"/"rdi"). Always false for 1D
bool isTopDown(const Texture& texture);

// Reverse the row order of every image in every level, and update
// "KTXorientation" to match. No-op for 1D textures
void flipY(Texture& texture);

//----------------------------------------------------------------------------//
// Reading and writing

struct WriteOptions
{
    Supercompression supercompression = Supercompression::Zstd;
    // zstd level: 1 (fastest) to 22 (smallest); negative is faster still,
    // 0 is zstd's own default (3). On texture data, 6 compresses faster than
    // zlib's default level and smaller in most cases
    int compressionLevel = 6;
    // Threads for compressing mip levels of 16 MiB or more: 0 = all hardware
    // threads, 1 = single-threaded. Multithreaded output is a few percent
    // larger, and decodes the same
    uint32_t threads = 0;
};

// Encode 'texture' as a KTX 2.0 file into 'out' (replacing its contents).
// Returns false and sets *error (if given) on failure
bool write
(
    const Texture& texture,
    std::vector<uint8_t>& out,
    const WriteOptions& options = WriteOptions(),
    std::string* error = nullptr
);

// Decode a KTX 2.0 file from memory into 'texture' (left untouched on
// failure). Returns false and sets *error (if given) on failure
bool read
(
    const void* data,
    size_t size,
    Texture& texture,
    std::string* error = nullptr
);

bool readFile
(
    const std::string& path,
    Texture& texture,
    std::string* error = nullptr
);

bool writeFile
(
    const std::string& path,
    const Texture& texture,
    const WriteOptions& options = WriteOptions(),
    std::string* error = nullptr
);

